import type { WorkShiftStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface WorkshiftStatusEntry {
  label: string;
  variant: BadgeVariants;
}

// Source of truth for work shift status display. Key order defines the
// user-visible filter order.
export const workshiftStatusBadge: Record<WorkShiftStatus, WorkshiftStatusEntry> = {
  ACTIVE: { label: 'Active', variant: 'success' },
  FINISHED: { label: 'Finished', variant: 'default' },
  TIMED_OUT: { label: 'Timed Out', variant: 'warning' },
  PAUSED: { label: 'Paused', variant: 'info' },
};

const defaultWorkshiftStatus: WorkshiftStatusEntry = { label: '', variant: 'default' };

// WorkShiftStatus keys are UPPERCASE, so snakeCaseToCapitalizedCase doesn't fit — fall back to the raw value.
export function getWorkshiftStatusBadge(status: WorkShiftStatus): WorkshiftStatusEntry {
  return workshiftStatusBadge[status] ?? { ...defaultWorkshiftStatus, label: status };
}

// Derived strictly from workshiftStatusBadge so the filter list and the badges
// can't drift. This intentionally includes PAUSED, which the old hand-written
// list omitted.
export const workshiftStatuses: SelectItem<WorkShiftStatus>[] = Object.entries(workshiftStatusBadge).map(
  ([value, { label }]) => ({ value: value as WorkShiftStatus, name: label })
);
